   103	function persistSingleOutput(
   104		outputPath: string | undefined,
   105		fullOutput: string,
   106	): { savedPath?: string; error?: string } {
   107		if (!outputPath) return {};
   108		try {
   109			fs.mkdirSync(path.dirname(outputPath), { recursive: true });
   110			fs.writeFileSync(outputPath, fullOutput, "utf-8");
   111			return { savedPath: outputPath };
   112		} catch (err) {
   113			return { error: err instanceof Error ? err.message : String(err) };
   114		}
   115	}
   116	
   117	export function resolveSingleOutput(
   118		outputPath: string | undefined,
   119		fallbackOutput: string,
   120		beforeRun: SingleOutputSnapshot | undefined,
   121	): { fullOutput: string; savedPath?: string; saveError?: string } {
   122		if (!outputPath) return { fullOutput: fallbackOutput };
   123	
   124		let changedSinceStart = false;
   125		try {
   126			const stat = fs.statSync(outputPath);
   127			changedSinceStart = !beforeRun?.exists
   128				|| stat.mtimeMs !== beforeRun.mtimeMs
   129				|| stat.size !== beforeRun.size;
   130		} catch (error) {
   131			const code = error && typeof error === "object" && "code" in error ? (error as { code?: unknown }).code : undefined;
   132			if (code !== "ENOENT" && code !== "ENOTDIR") {
   133				return {
   134					fullOutput: fallbackOutput,
   135					saveError: `Failed to inspect output file: ${error instanceof Error ? error.message : String(error)}`,
   136				};
   137			}
   138		}
   139	
   140		if (changedSinceStart) {
   141			try {
   142				return { fullOutput: fs.readFileSync(outputPath, "utf-8"), savedPath: outputPath };
   143			} catch (error) {
   144				return {
   145					fullOutput: fallbackOutput,
   146					saveError: `Failed to read changed output file: ${error instanceof Error ? error.message : String(error)}`,
   147				};
   148			}
   149		}
   150	
   151		const save = persistSingleOutput(outputPath, fallbackOutput);
   152		if (save.savedPath) return { fullOutput: fallbackOutput, savedPath: save.savedPath };
   153		return { fullOutput: fallbackOutput, saveError: save.error };
   154	}
   155	
   156	export function finalizeSingleOutput(params: {
   157		fullOutput: string;
   158		truncatedOutput?: string;
   159		outputPath?: string;
   160		outputMode?: OutputMode;
   161		exitCode: number;
   162		savedPath?: string;
   163		outputReference?: SavedOutputReference;
   164		saveError?: string;
   165	}): { displayOutput: string; savedPath?: string; outputReference?: SavedOutputReference; saveError?: string } {
   166		let displayOutput = params.truncatedOutput || params.fullOutput;
   167		if (params.exitCode === 0 && params.savedPath) {
   168			const outputReference = params.outputReference ?? formatSavedOutputReference(params.savedPath, params.fullOutput);
   169			if (params.outputMode === "file-only") {
   170				return { displayOutput: outputReference.message, savedPath: params.savedPath, outputReference };
   171			}
   172			displayOutput += `\n\n${outputReference.message}`;
   173			return { displayOutput, savedPath: params.savedPath, outputReference };
   174		}
   175		if (params.exitCode === 0 && params.saveError && params.outputPath) {
   176			displayOutput += `\n\nOutput file error: ${params.outputPath}\n${params.saveError}`;
   177			return { displayOutput, saveError: params.saveError };
   178		}
   179		return { displayOutput };
   180	}

