   115	function validateConfig(config: WorkflowConfig): void {
   116	  // ponytail: runtime config validation — the only safety we lose by opening
   117	  // Phase to string. Runs once at construction.
   118	  const seen = new Set<Phase>();
   119	  for (const p of config.phases) {
   120	    if (seen.has(p)) throw new Error(`WorkflowConfig: duplicate phase "${p}"`);
   121	    seen.add(p);
   122	  }
   123	  for (const p of Object.keys(config.phaseArtifacts)) {
   124	    if (!seen.has(p)) {
   125	      throw new Error(`WorkflowConfig: phaseArtifacts references unknown phase "${p}"`);
   126	    }
   127	  }
   128	  for (const p of Object.keys(config.prompts)) {
   129	    if (!seen.has(p)) {
   130	      throw new Error(`WorkflowConfig: prompts references unknown phase "${p}"`);
   131	    }
   132	  }
   133	  for (const r of config.skipRules ?? []) {
   134	    if (!seen.has(r.phase)) {
   135	      throw new Error(`WorkflowConfig: skipRule references unknown phase "${r.phase}"`);
   136	    }
   137	  }
