   259	    if (rule && await rule.shouldSkip({ artifactDir: this.artifactDir, userPrompt: this.userPrompt })) {
   260	      const skipTo = this.nextPhase(next) ?? next;
   261	      this.setPhase(skipTo);
   262	      return {
   263	        kind: "advanced",
   264	        phase: skipTo,
   265	        step: this.PHASE_STEP[skipTo],
   266	        prompt: this.promptFor(skipTo),
   267	        skipped: next,
   268	        entry: this.entryFor(skipTo, false),
   269	        footer: this.footerFor(),
   270	      };
   271	    }
   272	    this.setPhase(next);
   273	    return {
   274	      kind: "advanced",
   275	      phase: next,
   276	      step: this.PHASE_STEP[next],
   277	      prompt: this.promptFor(next),
   278	      entry: this.entryFor(next, false),
   279	      footer: this.footerFor(),
   280	    };
   281	  }
   282	
   283	  // ── Public methods: one per adapter call site ──
   284	
   285	  async start(goal: string, deps: WorkflowDeps): Promise<WorkflowEffect> {
   286	    if (this.active) {
   287	      return { kind: "alreadyActive", phase: this.phase, step: this.PHASE_STEP[this.phase] };
   288	    }
   289	    this.userPrompt = goal.trim();
   290	    const base = this.config.artifactsBase ?? "./.selesai/artifacts";
   291	    this.artifactDir = deps.artifactPathFor(this.userPrompt, base);
   292	    await deps.mkdirArtifactDir(this.artifactDir);
   293	    this.active = true;
   294	    this.setPhase(this.config.phases[0]);
   295	    const prompt = this.promptFor(this.config.phases[0]);
   296	    return {
   297	      kind: "started",
   298	      phase: this.config.phases[0],
   299	      step: 1,
   300	      prompt,
   301	      entry: this.entryFor(this.config.phases[0], false),
   302	      footer: this.footerFor(),
   303	    };
   304	  }
   305	
   306	  async next(deps: WorkflowDeps): Promise<WorkflowEffect> {
   307	    if (!this.active) return { kind: "idle", phase: this.phase };
   308	    return this.advancePhase(deps);
   309	  }
   310	
   311	  async end(deps: WorkflowDeps): Promise<WorkflowEffect> {
   312	    if (!this.active) return { kind: "idle", phase: this.phase };
   313	    const last = this.config.phases[this.config.phases.length - 1];
   314	    if (this.phase !== last) {
   315	      return { kind: "endBlocked", phase: this.phase, missing: `not at terminal (${last})` };
   316	    }
   317	    for (const file of this.config.closeArtifacts) {
   318	      if (!(await deps.fileExists(`${this.artifactDir}/${file}`))) {
   319	        return { kind: "endBlocked", phase: this.phase, missing: file };
   320	      }
   321	    }
   322	    this.active = false;
   323	    const entry = this.entryFor(this.phase, true);
   324	    return {
   325	      kind: "closed",
   326	      phase: this.phase,
   327	      artifactDir: this.artifactDir,
   328	      entry,
   329	      footer: this.footerFor(),
   330	    };
   331	  }
   332	
   333	  // ponytail: the tool_result auto-advance hook. One call, one apply.
   334	  // Reentrancy guard + autoArmed + artifact gate all live in here — the
   335	  // adapter's hook is `const eff = await sm.onArtifactMaybe(deps); apply(...)`.
   336	  async onArtifactMaybe(deps: WorkflowDeps): Promise<WorkflowEffect> {
   337	    if (this.advancing) return { kind: "noOp" };
   338	    if (!this.active || !this.autoArmed) return { kind: "noOp" };
   339	    const expected = this.config.phaseArtifacts[this.phase];
   340	    if (!expected) return { kind: "noOp" };
   341	    // Acquire synchronously before any await so a concurrent call sees advancing=true.
   342	    this.advancing = true;
   343	    try {
   344	      // Artifact must exist at the workflow-owned path. No rescue/redirect magic.
   345	      if (!(await this.artifactExistsFor(this.phase, deps))) return { kind: "noOp" };
   346	      this.autoArmed = false;
   347	      const out = await this.advancePhase(deps, true);
   348	      if (out.kind === "terminalReady") {
   349	        // ponytail: both close artifacts present — close directly.
   350	        return this.end(deps);
   351	      }
   352	      if (out.kind === "terminalNeedsArtifacts") {
   353	        // Keep listening: audit/review may land in separate writes.
   354	        this.autoArmed = true;
   355	      }
   356	      return out;
   357	    } finally {
   358	      this.advancing = false;
   359	    }
   360	  }

