    10	
    11	export function normalizeSingleOutputOverride(
    12		output: string | boolean | undefined,
    13		defaultOutput: string | undefined,
    14	): string | false | undefined {
    15		if (output === false || output === "false") return false;
    16		if (output === true || output === "true") return defaultOutput;
    17		if (typeof output === "string" && output.length > 0) return output;
    18		return undefined;
    19	}
    20	
    21	export function resolveSingleOutputPath(
    22		output: string | boolean | undefined,
    23		runtimeCwd: string,
    24		requestedCwd?: string,
    25		relativeBaseDir?: string,
    26	): string | undefined {
    27		if (typeof output !== "string" || !output || output === "false" || output === "true") return undefined;
    28		if (path.isAbsolute(output)) return output;
