   104		outputPath: string | undefined,
   105		fullOutput: string,
   106	): { savedPath?: string; error?: string } {
   107		if (!outputPath) return {};
   108		try {
   109			fs.mkdirSync(path.dirname(outputPath), { recursive: true });
   110			fs.writeFileSync(outputPath, fullOutput, "utf-8");
   111			return { savedPath: outputPath };
   112		} catch (err) {
   113			return { error: err instanceof Error ? err.message : String(err) };
   114		}
