   116	
   117	export function resolveSingleOutput(
   118		outputPath: string | undefined,
   119		fallbackOutput: string,
   120		beforeRun: SingleOutputSnapshot | undefined,
   121	): { fullOutput: string; savedPath?: string; saveError?: string } {
   122		if (!outputPath) return { fullOutput: fallbackOutput };
   123	
   124		let changedSinceStart = false;
   125		try {
   126			const stat = fs.statSync(outputPath);
   127			changedSinceStart = !beforeRun?.exists
   128				|| stat.mtimeMs !== beforeRun.mtimeMs
   129				|| stat.size !== beforeRun.size;
   130		} catch (error) {
   131			const code = error && typeof error === "object" && "code" in error ? (error as { code?: unknown }).code : undefined;
   132			if (code !== "ENOENT" && code !== "ENOTDIR") {
   133				return {
   134					fullOutput: fallbackOutput,
   135					saveError: `Failed to inspect output file: ${error instanceof Error ? error.message : String(error)}`,
   136				};
   137			}
   138		}
   139	
   140		if (changedSinceStart) {
   141			try {
   142				return { fullOutput: fs.readFileSync(outputPath, "utf-8"), savedPath: outputPath };
   143			} catch (error) {
   144				return {
   145					fullOutput: fallbackOutput,
   146					saveError: `Failed to read changed output file: ${error instanceof Error ? error.message : String(error)}`,
   147				};
   148			}
   149		}
   150	
   151		const save = persistSingleOutput(outputPath, fallbackOutput);
   152		if (save.savedPath) return { fullOutput: fallbackOutput, savedPath: save.savedPath };
   153		return { fullOutput: fallbackOutput, saveError: save.error };
   154	}
