   156	export function finalizeSingleOutput(params: {
   157		fullOutput: string;
   158		truncatedOutput?: string;
   159		outputPath?: string;
   160		outputMode?: OutputMode;
   161		exitCode: number;
   162		savedPath?: string;
   163		outputReference?: SavedOutputReference;
   164		saveError?: string;
   165	}): { displayOutput: string; savedPath?: string; outputReference?: SavedOutputReference; saveError?: string } {
   166		let displayOutput = params.truncatedOutput || params.fullOutput;
   167		if (params.exitCode === 0 && params.savedPath) {
   168			const outputReference = params.outputReference ?? formatSavedOutputReference(params.savedPath, params.fullOutput);
   169			if (params.outputMode === "file-only") {
   170				return { displayOutput: outputReference.message, savedPath: params.savedPath, outputReference };
   171			}
   172			displayOutput += `\n\n${outputReference.message}`;
   173			return { displayOutput, savedPath: params.savedPath, outputReference };
   174		}
   175		if (params.exitCode === 0 && params.saveError && params.outputPath) {
   176			displayOutput += `\n\nOutput file error: ${params.outputPath}\n${params.saveError}`;
   177			return { displayOutput, saveError: params.saveError };
   178		}
   179		return { displayOutput };
   180	}

