   126	    }
   127	  }
   128	  for (const p of Object.keys(config.prompts)) {
   129	    if (!seen.has(p)) {
   130	      throw new Error(`WorkflowConfig: prompts references unknown phase "${p}"`);
   131	    }
   132	  }
