     7	function keepTopLevelParameterDescriptions<T>(schema: T): T {
     8		return pruneNestedDescriptions(schema, []) as T;
     9	}
    10	
    11	function pruneNestedDescriptions(value: unknown, path: string[]): unknown {
    12		if (!value || typeof value !== "object") return value;
    13	
    14		const result = Array.isArray(value) ? [] : Object.create(Object.getPrototypeOf(value));
    15		for (const key of Reflect.ownKeys(value)) {
    16			const descriptor = Object.getOwnPropertyDescriptor(value, key);
    17			if (!descriptor) continue;
    18			if (key === "description" && !isTopLevelParameterDescription(path)) continue;
    19			if ("value" in descriptor) {
    20				const nextPath = typeof key === "string" ? [...path, key] : path;
    21				descriptor.value = pruneNestedDescriptions(descriptor.value, nextPath);
    22			}
    23			Object.defineProperty(result, key, descriptor);
    24		}
    25		return result;
    26	}
    27	
    28	function isTopLevelParameterDescription(path: string[]): boolean {
    29		return path.length === 2 && path[0] === "properties";
    30	}
