    27		if (typeof output !== "string" || !output || output === "false" || output === "true") return undefined;
    28		if (path.isAbsolute(output)) return output;
    29		if (relativeBaseDir) return path.resolve(relativeBaseDir, output);
    30		const baseCwd = requestedCwd
    31			? (path.isAbsolute(requestedCwd) ? requestedCwd : path.resolve(runtimeCwd, requestedCwd))
    32			: runtimeCwd;
    33		return path.resolve(baseCwd, output);
