    61	function formatByteSize(bytes: number): string {
    62		if (bytes < 1024) return `${bytes} B`;
    63		const units = ["KB", "MB", "GB", "TB"];
    64		let value = bytes / 1024;
    65		let unitIndex = 0;
    66		while (value >= 1024 && unitIndex < units.length - 1) {
    67			value /= 1024;
    68			unitIndex++;
    69		}
    70		return `${value.toFixed(1)} ${units[unitIndex]}`;
    71	}
