    73	export function formatSavedOutputReference(savedPath: string, fullOutput: string): SavedOutputReference {
    74		const absolutePath = path.resolve(savedPath);
    75		const bytes = Buffer.byteLength(fullOutput, "utf-8");
    76		const lines = countLines(fullOutput);
    77		return {
    78			path: absolutePath,
    79			bytes,
    80			lines,
    81			message: `Output saved to: ${absolutePath} (${formatByteSize(bytes)}, ${lines} ${lines === 1 ? "line" : "lines"}). Read this file if needed.`,
    82		};
