    60	// the child `output` path; child processes do not share the parent's workflow
    61	// state, so the parent-scoped write_workflow_artifact tool cannot help there.
    62	const FORCE_OUTPUT_PHASES = new Set<Phase>(["plan", "reuse", "handoff", "audit"]);
    63	
    64	// ponytail: phases where the parent can save subagent text as the artifact
    65	// when the child did not write the file itself (dumb/local models).
