   225	// ponytail: apply side effects for effects that carry entry/footer/prompt.
   226	// Terminal/blocked/idle/noOp/alreadyActive carry none — the adapter's call
   227	// site formats the tool result from the effect's domain fields + config.
   228	function applyEffect(
   229	  pi: ExtensionAPI,
   230	  ctx: ExtensionContext,
   231	  config: WorkflowConfig,
   232	  eff: WorkflowEffect,
   233	): void {
   234	  switch (eff.kind) {
   235	    case "started":
   236	    case "advanced":
   237	      if ("entry" in eff) applyEntry(pi, config, eff.entry);
   238	      if ("footer" in eff) applyFooter(ctx, eff.footer);
   239	      if (eff.prompt) continueAgent(pi, ctx, eff.prompt);
   240	      return;
   241	    case "closed":
   242	      if ("entry" in eff) applyEntry(pi, config, eff.entry);
   243	      if ("footer" in eff) applyFooter(ctx, eff.footer);
   244	      ctx.ui.notify(
   245	        `${config.footerLabel} workflow complete. Artifacts: ${eff.artifactDir}`,
   246	        "info",
   247	      );
   248	      return;
   249	    case "terminalNeedsArtifacts":
   250	      if (eff.promptToQueue) continueAgent(pi, ctx, eff.promptToQueue);
   251	      return;
   252	    case "blocked":
   253	    case "terminalReady":
   254	    case "endBlocked":
   255	    case "idle":
   256	    case "noOp":
   257	    case "alreadyActive":
   258	      return;
   259	  }
   260	}
