   319	    // commits). Shared by every mode today; a mode that wants a different rule
   320	    // supplies its own skipRules in config and we respect them as-is.
   321	    const skipRules = config.skipRules ?? [
   322	      {
   323	        phase: "reuse",
   324	        shouldSkip: async () => isEmptyProject(pi),
   325	      },
   326	    ];
