   334	    // ── start tool ──
   335	    pi.registerTool({
   336	      name: start,
   337	      label: options.toolLabels.start,
   338	      description: `Start the ${mode} workflow for the given goal. Sets up grilling as the first phase and returns the grilling prompt. Do not call if a workflow is already active.`,
   339	      promptSnippet: `${start}(goal) - start the ${mode} workflow; goal is what the user wants to build.`,
   340	      promptGuidelines: [
   341	        `Call ${start} only when the user explicitly asks to start a ${mode} workflow and none is active.`,
   342	        "Pass the user's full goal as the goal parameter.",
   343	      ],
   344	      parameters: Type.Object({
   345	        goal: Type.String({
   346	          description: `What the user wants the ${mode} workflow to build or accomplish.`,
   347	        }),
   348	      }),
   349	      async execute(_id, params, _signal, _onUpdate, ctx) {
   350	        const other = activeControllersFor(pi).find((c) => c.sm !== sm);
   351	        if (other) {
   352	          return {
   353	            content: [{ type: "text", text: `A ${other.config.mode} workflow is already active (phase: ${other.sm.snapshot.phase}). Close it before starting ${mode}.` }],
   354	            details: { phase: other.sm.snapshot.phase, alreadyActive: true },
   355	          };
   356	        }
   357	        const eff = await sm.start(params.goal, deps);
   358	        applyEffect(pi, ctx, config, eff);
   359	        if (eff.kind === "alreadyActive") {
   360	          return {
   361	            content: [
   362	              {
   363	                type: "text",
   364	                text: `A ${mode} workflow is already active (phase: ${eff.phase}). Do not call ${start} again. Phases auto-advance as artifacts land; call ${end} only from the final phase.`,
   365	              },
   366	            ],
   367	            details: { phase: eff.phase, alreadyActive: true },
   368	          };
   369	        }
