   529	    // ── /<command> ──
   530	    pi.registerCommand(options.commandName, {
   531	      description: options.commandDescription,
   532	      handler: async (args: string, ctx: ExtensionCommandContext) => {
   533	        if (!ctx.isIdle()) {
   534	          ctx.ui.notify(
   535	            `Agent is busy. Wait for it to finish before calling /${options.commandName}.`,
   536	            "warning",
   537	          );
