    68	function textFromToolResultContent(content: unknown): string | undefined {
    69	  if (!Array.isArray(content)) return undefined;
    70	  const parts: string[] = [];
    71	  for (const part of content) {
    72	    if (part && typeof part === "object" && (part as any).type === "text" && typeof (part as any).text === "string") {
    73	      parts.push((part as any).text);
    74	    }
