    80	// ponytail: rewrite the subagent tool input so the child writes its output
    81	// directly to ${artifactDir}/${file} as an absolute path. Absolute paths pass
    82	// through resolveSingleOutputPath verbatim, so injectOutputPathSystemPrompt
    83	// then forces the child to the correct location instead of repo root.
    84	// Mutates `input` in place (tool_call handlers can patch event.input).
    85	// No-op unless the workflow is active, in a force-output phase, and the call
    86	// targets the `subagent` tool. Respects an explicit absolute caller output.
    87	function forceSubagentOutputToArtifactDir(
    88	  input: Record<string, unknown>,
    89	  artifactDir: string,
    90	  file: string,
    91	  onlyAgents?: Set<string>,
    92	): void {
    93	  const dest = resolve(artifactDir, file);
    94	  const shouldForce = (agent: string) => !onlyAgents || onlyAgents.has(agent);
    95	  // Single-agent call: { agent, task, output?, ... }
    96	  if (typeof input.agent === "string") {
    97	    if (!shouldForce(input.agent)) return;
    98	    const existing = input.output;
    99	    if (typeof existing === "string" && isAbsolute(existing)) return; // caller pinned it
   100	    input.output = dest;
   101	    return;
   102	  }
   103	  // Top-level parallel: { tasks: [{ agent, output? }, ...] }
   104	  if (Array.isArray(input.tasks)) {
   105	    for (const task of input.tasks) {
   106	      if (task && typeof task === "object" && typeof task.agent === "string" && shouldForce(task.agent)) {
   107	        const ex = task.output;
   108	        if (typeof ex === "string" && isAbsolute(ex)) continue;
   109	        task.output = dest;
   110	      }
   111	    }
   112	    return;
   113	  }
   114	  // Chain: { chain: [{ agent, output?, parallel: [{ agent, output? }] }] }
   115	  if (Array.isArray(input.chain)) {
   116	    for (const step of input.chain) {
   117	      if (!step || typeof step !== "object") continue;
   118	      if (typeof step.agent === "string" && shouldForce(step.agent)) {
   119	        const ex = step.output;
   120	        if (!(typeof ex === "string" && isAbsolute(ex))) step.output = dest;
   121	      }
   122	      if (Array.isArray(step.parallel)) {
   123	        for (const task of step.parallel) {
   124	          if (task && typeof task === "object" && typeof task.agent === "string" && shouldForce(task.agent)) {
   125	            const ex = task.output;
   126	            if (!(typeof ex === "string" && isAbsolute(ex))) task.output = dest;
   127	          }
   128	        }
   129	      }
   130	    }
   131	  }
   132	}
