   213	function continueAgent(pi: ExtensionAPI, ctx: ExtensionContext, prompt: string): void {
   214	  // ponytail: agent is mid-turn (streaming) when tool_result fires, so a bare
   215	  // sendUserMessage() throws "Agent is already processing". deliverAs:"followUp"
