   262	function registerSharedArtifactWriter(pi: ExtensionAPI): void {
   263	  if (registry.writerRegisteredFor.has(pi)) return;
   264	  registry.writerRegisteredFor.add(pi);
   265	  pi.registerTool({
   266	    name: WORKFLOW_ARTIFACT_TOOL,
   267	    label: "Write Workflow Artifact",
   268	    description: "Write the current workflow phase artifact. The workflow enforces the destination path; provide content only.",
   269	    promptSnippet: `${WORKFLOW_ARTIFACT_TOOL}(content) - write the active workflow artifact; path is chosen by the workflow, not the agent.`,
   270	    promptGuidelines: [
   271	      `During any workflow, use ${WORKFLOW_ARTIFACT_TOOL} instead of write/edit for workflow artifacts.`,
   272	      "Provide artifact content only; do not provide a path.",
   273	    ],
   274	    parameters: Type.Object({
   275	      content: Type.String({ description: "Artifact markdown/text content to save." }),
   276	    }),
   277	    async execute(_id, params, _signal, _onUpdate, ctx) {
   278	      const active = activeControllersFor(pi);
   279	      if (active.length !== 1) {
   280	        const msg = active.length === 0
   281	          ? "No active workflow."
   282	          : `Multiple active workflows (${active.map((c) => c.config.mode).join(", ")}); close one first.`;
   283	        return { content: [{ type: "text", text: msg }], details: { active: active.length } };
   284	      }
   285	      const controller = active[0]!;
   286	      const snap = controller.sm.snapshot;
   287	      const file = controller.config.phaseArtifacts[snap.phase];
   288	      if (!file) {
   289	        return {
   290	          content: [{ type: "text", text: `Phase ${snap.phase} has no workflow artifact.` }],
   291	          details: { phase: snap.phase, blocked: true },
   292	        };
   293	      }
   294	      const path = resolve(snap.artifactDir, file);
   295	      await mkdir(snap.artifactDir, { recursive: true });
   296	      await writeFile(path, params.content, "utf8");
   297	      const eff = await controller.sm.onArtifactMaybe(controller.deps);
   298	      applyEffect(pi, ctx, controller.config, eff);
   299	      return {
   300	        content: [{ type: "text", text: `Wrote ${path}.` }],
   301	        details: { mode: controller.config.mode, phase: snap.phase, path, file },
   302	      };
   303	    },
   304	    renderResult(result, _options, theme) {
   305	      const d = result.details as { path?: string; blocked?: boolean };
   306	      if (d.blocked) return new Text(theme.fg("warning", "○ workflow artifact not written"), 0, 0);
   307	      return new Text(theme.fg(d.path ? "success" : "warning", d.path ? `✓ wrote ${d.path}` : "○ no active workflow"), 0, 0);
   308	    },
   309	  } satisfies ToolDefinition);
   310	}
